class Solution {
public:
    vector<int> findAllPeople(int n, vector<vector<int>>& meetings, int firstPerson) {
        map<int, vector<pair<int, int>>> timeGroups;
        for (const auto& m : meetings) {
            timeGroups[m[2]].push_back({m[0], m[1]});
        }
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto self, int x) -> int {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        auto unite = [&](int x, int y) {
            int rx = find(find, x), ry = find(find, y);
            if (rx != ry) parent[rx] = ry;
        };
        unite(0, firstPerson);
        for (const auto& pair : timeGroups) {
            unordered_set<int> pool;
            for (const auto& edge : pair.second) {
                unite(edge.first, edge.second);
                pool.insert(edge.first);
                pool.insert(edge.second);
            }
            int root0 = find(find, 0);
            for (int p : pool) {
                if (find(find, p) != root0) {
                    parent[p] = p;
                }
            }
        }
        int root0 = find(find, 0);
        vector<int> res;
        for (int i = 0; i < n; ++i) {
            if (find(find, i) == root0) res.push_back(i);
        }
        return res;
    }
};

class Solution {
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        TreeMap<Integer, List<int[]>> timeGroups = new TreeMap<>();
        for (int[] m : meetings) {
            timeGroups.computeIfAbsent(m[2], k -> new ArrayList<>()).add(new int[]{m[0], m[1]});
        }
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        union(parent, 0, firstPerson);
        for (List<int[]> batch : timeGroups.values()) {
            Set<Integer> pool = new HashSet<>();
            for (int[] edge : batch) {
                union(parent, edge[0], edge[1]);
                pool.add(edge[0]);
                pool.add(edge[1]);
            }
            int root0 = find(parent, 0);
            for (int person : pool) {
                if (find(parent, person) != root0) {
                    parent[person] = person;
                }
            }
        }
        int root0 = find(parent, 0);
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (find(parent, i) == root0) res.add(i);
        }
        return res;
    }
    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    private void union(int[] parent, int x, int y) {
        int rx = find(parent, x), ry = find(parent, y);
        if (rx != ry) parent[rx] = ry;
    }
}

var findAllPeople = function(n, meetings, firstPerson) {
    const timeGroups = new Map();
    for (const [u, v, t] of meetings) {
        if (!timeGroups.has(t)) timeGroups.set(t, []);
        timeGroups.get(t).push([u, v]);
    }
    const sortedTimes = Array.from(timeGroups.keys()).sort((a, b) => a - b);
    const parent = Array.from({ length: n }, (_, i) => i);
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent[rx] = ry;
    };
    union(0, firstPerson);
    for (const t of sortedTimes) {
        const batch = timeGroups.get(t);
        const pool = new Set();
        for (const [u, v] of batch) {
            union(u, v);
            pool.add(u);
            pool.add(v);
        }
        const root0 = find(0);
        for (const person of pool) {
            if (find(person) !== root0) {
                parent[person] = person;
            }
        }
    }
    const root0 = find(0);
    const res = [];
    for (let i = 0; i < n; i++) {
        if (find(i) === root0) res.push(i);
    }
    return res;
};
